```python
def remove_duplicates_with_custom_value(t, custom_value="DUPLICATE"):
    """
    Removes elements from a tuple that appear more than once,
    replacing duplicates with a custom value.

    Parameters:
    t (tuple): The input tuple.
    custom_value: The value to replace duplicates with. Default is "DUPLICATE".

    Returns:
    tuple: A new tuple with duplicates replaced by the custom value.
    """
    seen = {}
    result = []

    for item in t:
        if item in seen:
            seen[item] += 1
        else:
            seen[item] = 1

    for item in t:
        if seen[item] > 1:
            result.append(custom_value)
        else:
            result.append(item)

    return tuple(result)
```

